// Stock Visualization with D3.js v6
// Bubble chart with force simulation + interactive data table

(function() {
    'use strict';

    // Configuration
    const config = {
        bubbleChart: {
            width: 700,
            height: 500,
            margin: { top: 20, right: 20, bottom: 20, left: 20 }
        },
        minBubbleRadius: 15,
        maxBubbleRadius: 50,
        etfRadius: 20
    };

    // Color scale for sectors
    const sectorColors = {
        'Information Technology': '#4299e1',
        'Industry': '#48bb78',
        'Energy': '#ed8936',
        'Financial': '#9f7aea',
        'ETF': '#a0aec0'
    };

    // Sector center positions for force clustering
    const sectorCenters = {
        'Information Technology': { x: 0.25, y: 0.35 },
        'Industry': { x: 0.75, y: 0.35 },
        'Energy': { x: 0.25, y: 0.7 },
        'Financial': { x: 0.75, y: 0.7 },
        'ETF': { x: 0.5, y: 0.5 }
    };

    // Format market cap for display
    function formatMarketCap(value) {
        if (!value || isNaN(value)) return 'N/A';
        const num = parseFloat(value);
        if (num >= 1e12) return (num / 1e12).toFixed(2) + 'T';
        if (num >= 1e9) return (num / 1e9).toFixed(2) + 'B';
        if (num >= 1e6) return (num / 1e6).toFixed(2) + 'M';
        return num.toLocaleString();
    }

    // State management
    let selectedTicker = null;
    let stockData = [];
    let simulation = null;

    // Load and process data
    d3.csv('data/stock-descriptions.csv').then(function(data) {
        // Process data
        stockData = data.map(function(d) {
            const isETF = d.sector === 'ETF';
            return {
                ticker: d.ticker,
                sector: d.sector,
                name: d['full name'] || d.ticker,
                marketCap: d.marketCap ? parseFloat(d.marketCap) : null,
                country: d.country || null,
                website: d.website || null,
                isETF: isETF
            };
        }).filter(function(d) {
            return d.ticker && d.sector;
        });

        // Sort data deterministically
        stockData.sort(function(a, b) {
            if (a.sector !== b.sector) return a.sector.localeCompare(b.sector);
            return a.ticker.localeCompare(b.ticker);
        });

        // Create visualizations
        createBubbleChart();
        createLegend();
        createDataTable();
    }).catch(function(error) {
        console.error('Error loading data:', error);
    });

    function createBubbleChart() {
        const container = d3.select('#bubble-chart');
        const width = config.bubbleChart.width;
        const height = config.bubbleChart.height;

        // Create SVG
        const svg = container.append('svg')
            .attr('viewBox', '0 0 ' + width + ' ' + height)
            .attr('preserveAspectRatio', 'xMidYMid meet');

        // Calculate radius scale based on market cap
        const marketCaps = stockData
            .filter(function(d) { return d.marketCap && !d.isETF; })
            .map(function(d) { return d.marketCap; });

        const radiusScale = d3.scaleSqrt()
            .domain([d3.min(marketCaps), d3.max(marketCaps)])
            .range([config.minBubbleRadius, config.maxBubbleRadius]);

        // Assign initial positions and radii
        stockData.forEach(function(d, i) {
            const center = sectorCenters[d.sector] || { x: 0.5, y: 0.5 };
            d.x = center.x * width + (i % 5 - 2) * 10;
            d.y = center.y * height + (Math.floor(i / 5) % 3 - 1) * 10;
            d.radius = d.isETF ? config.etfRadius : radiusScale(d.marketCap || d3.min(marketCaps));
        });

        // Create force simulation
        simulation = d3.forceSimulation(stockData)
            .force('x', d3.forceX(function(d) {
                const center = sectorCenters[d.sector] || { x: 0.5, y: 0.5 };
                return center.x * width;
            }).strength(0.15))
            .force('y', d3.forceY(function(d) {
                const center = sectorCenters[d.sector] || { x: 0.5, y: 0.5 };
                return center.y * height;
            }).strength(0.15))
            .force('collide', d3.forceCollide(function(d) {
                return d.radius + 2;
            }).strength(1))
            .force('center', d3.forceCenter(width / 2, height / 2).strength(0.05));

        // Create bubble groups
        const bubbles = svg.selectAll('.bubble-group')
            .data(stockData)
            .enter()
            .append('g')
            .attr('class', 'bubble-group')
            .attr('data-ticker', function(d) { return d.ticker; });

        // Add circles
        bubbles.append('circle')
            .attr('class', 'bubble')
            .attr('r', function(d) { return d.radius; })
            .attr('fill', function(d) { return sectorColors[d.sector] || '#999'; })
            .on('click', function(event, d) {
                selectStock(d.ticker);
            })
            .on('mouseenter', function(event, d) {
                if (!d.isETF) {
                    showTooltip(event, d);
                }
            })
            .on('mousemove', function(event, d) {
                if (!d.isETF) {
                    moveTooltip(event);
                }
            })
            .on('mouseleave', function() {
                hideTooltip();
            });

        // Add labels
        bubbles.append('text')
            .attr('class', 'bubble-label')
            .text(function(d) { return d.ticker; })
            .style('font-size', function(d) {
                return Math.max(8, Math.min(12, d.radius / 2.5)) + 'px';
            });

        // Run simulation for fixed number of ticks for determinism
        simulation.on('tick', function() {
            bubbles.attr('transform', function(d) {
                // Keep bubbles within bounds
                d.x = Math.max(d.radius, Math.min(width - d.radius, d.x));
                d.y = Math.max(d.radius, Math.min(height - d.radius, d.y));
                return 'translate(' + d.x + ',' + d.y + ')';
            });
        });

        // Run simulation to completion
        simulation.alpha(1).restart();
    }

    function createLegend() {
        const legend = d3.select('#legend');
        const sectors = Object.keys(sectorColors).sort();

        sectors.forEach(function(sector) {
            const item = legend.append('div').attr('class', 'legend-item');
            item.append('div')
                .attr('class', 'legend-color')
                .style('background-color', sectorColors[sector]);
            item.append('span').text(sector);
        });
    }

    function createDataTable() {
        const tbody = d3.select('#stock-table tbody');

        const rows = tbody.selectAll('tr')
            .data(stockData)
            .enter()
            .append('tr')
            .attr('data-ticker', function(d) { return d.ticker; })
            .on('click', function(event, d) {
                selectStock(d.ticker);
            });

        rows.append('td').text(function(d) { return d.ticker; });
        rows.append('td').text(function(d) { return d.name; });
        rows.append('td').text(function(d) { return d.sector; });
        rows.append('td').text(function(d) { return formatMarketCap(d.marketCap); });
    }

    function selectStock(ticker) {
        // Toggle selection
        if (selectedTicker === ticker) {
            selectedTicker = null;
        } else {
            selectedTicker = ticker;
        }

        // Update bubble selection
        d3.selectAll('.bubble').classed('selected', function(d) {
            return d.ticker === selectedTicker;
        });

        // Update table selection
        d3.selectAll('#stock-table tbody tr')
            .classed('selected', false)
            .classed('highlighted', function() {
                return d3.select(this).attr('data-ticker') === selectedTicker;
            });

        // Scroll table row into view
        if (selectedTicker) {
            const row = document.querySelector('#stock-table tbody tr[data-ticker="' + selectedTicker + '"]');
            if (row) {
                row.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
    }

    function showTooltip(event, d) {
        const tooltip = d3.select('#tooltip');
        tooltip.html(
            '<div class="ticker">' + d.ticker + '</div>' +
            '<div class="name">' + d.name + '</div>' +
            '<div class="sector">Sector: ' + d.sector + '</div>'
        );
        tooltip.classed('visible', true);
        moveTooltip(event);
    }

    function moveTooltip(event) {
        const tooltip = d3.select('#tooltip');
        const tooltipNode = tooltip.node();
        const tooltipRect = tooltipNode.getBoundingClientRect();

        let left = event.pageX + 15;
        let top = event.pageY - 10;

        // Keep tooltip within viewport
        if (left + tooltipRect.width > window.innerWidth) {
            left = event.pageX - tooltipRect.width - 15;
        }
        if (top + tooltipRect.height > window.innerHeight) {
            top = event.pageY - tooltipRect.height - 10;
        }

        tooltip
            .style('left', left + 'px')
            .style('top', top + 'px');
    }

    function hideTooltip() {
        d3.select('#tooltip').classed('visible', false);
    }

})();
ENDOFJS
